	private static LayerDefinition southBird() {
		MeshDefinition mesh = new MeshDefinition();
		PartDefinition root = mesh.getRoot();
		root.addOrReplaceChild("body", CubeListBuilder.create()
						.texOffs(0, 0).addBox(-3f, 13f, -4f, 6f, 6f, 8f),
				PartPose.offset(0f, 0f, 0f));
		root.addOrReplaceChild("head", CubeListBuilder.create()
						.texOffs(0, 14).addBox(-2.5f, -5f, -4f, 5f, 5f, 5f)
						.texOffs(20, 14).addBox(-1f, -3f, -9f, 2f, 2f, 5f),
				PartPose.offset(0f, 14f, -4f));
		root.addOrReplaceChild("leg0", CubeListBuilder.create()
						.texOffs(34, 14).addBox(-0.5f, 0f, -0.5f, 1f, 5f, 1f),
				PartPose.offset(-1.5f, 19f, 0f));
		root.addOrReplaceChild("leg1", CubeListBuilder.create()
						.texOffs(38, 14).addBox(-0.5f, 0f, -0.5f, 1f, 5f, 1f),
				PartPose.offset(1.5f, 19f, 0f));
		root.addOrReplaceChild("wing0", CubeListBuilder.create()
						.texOffs(28, 0).addBox(-1f, 0f, 0f, 1f, 4f, 7f),
				PartPose.offset(-3f, 14f, -3f));
		root.addOrReplaceChild("wing1", CubeListBuilder.create()
						.texOffs(44, 0).addBox(0f, 0f, 0f, 1f, 4f, 7f),
				PartPose.offset(3f, 14f, -3f));
		root.addOrReplaceChild("tail", CubeListBuilder.create()
						.texOffs(42, 14).addBox(-2f, 0f, 0f, 4f, 1f, 5f),
				PartPose.offsetAndRotation(0f, 15f, 4f, -0.3f, 0f, 0f));
		return LayerDefinition.create(mesh, 64, 32);
	}

